class Solution {
    public int[] memLeak(int memory1,int memory2){
        int time=1;
        while(Math.max(memory1,memory2)>=time){
            if(memory1>=memory2)memory1-=time;
            else memory2-=time;
            time++;
        }
        return new int[]{
            time,memory1,memory2
        };
    }
}

code.kotlin:
class Solution {
    fun memLeak(memory1Value:Int,memory2Value:Int):IntArray{
        var memory1=memory1Value;
        var memory2=memory2Value;
        var time=1;
        while(maxOf(memory1,memory2)>=time){
            if(memory1>=memory2)memory1-=time else memory2-=time;
            time++
        };
        return intArrayOf(time,memory1,memory2)
    }
}

code.cpp:
class Solution {
    public: vector<int> memLeak(int memory1,int memory2){
        int time=1;
        while(max(memory1,memory2)>=time){
            (memory1>=memory2?memory1:memory2)-=time++;
        }
        return {
            time,memory1,memory2
        };
    }
};
